* Signal source on vp (non-inverting input)
Vin vp 0 DC 0.9 AC 1 PULSE(0.8 1.0 10n 1n 1n 200n 500n)

.control
* 1. Operating Point
op
let pwr = -i(VDD) * 1.8
print pwr

* 2. AC Open-Loop Analysis
ac dec 100 10 100MEG
let aol_db = vdb(Vout)
let phase = 180/PI * cph(v(Vout))

meas ac dc_gain find aol_db at=10
meas ac f_3db when aol_db=dc_gain-3 fall=1
meas ac fun when aol_db=0 fall=1
meas ac phase_fun find phase when aol_db=0 fall=1
let pm = phase_fun + 180
print pm

* Transconductance estimation: gm = 2 * PI * fun * CL
let gm_calc = 2 * PI * fun * 1e-12
print gm_calc

* 3. Transient Slewing
tran 1n 600n
meas tran vout_init find v(Vout) at=10n
meas tran vout_peak max v(Vout)
meas tran slew_rate trig v(Vout) val=0.85 rise=1 targ v(Vout) val=0.95 rise=1

quit
.endc
.end

